import boto3
from typing import List

def extract_tables_from_document(file_bytes: bytes) -> List[List[List[str]]]:
    """
    Extracts table cells and row structure from a document using Amazon Textract.
    Returns a list of tables, where each table is a list of rows, and each row is a list of cell text strings.
    """
    client = boto3.client('textract')

    response = client.analyze_document(
        Document={'Bytes': file_bytes},
        FeatureTypes=['TABLES']
    )

    blocks = response.get('Blocks', [])

    while 'NextToken' in response:
        response = client.analyze_document(
            Document={'Bytes': file_bytes},
            NextToken=response['NextToken'],
            FeatureTypes=['TABLES']
        )
        blocks.extend(response.get('Blocks', []))

    block_map = {b['Id']: b for b in blocks}
    tables_data = []

    for block in blocks:
        if block['BlockType'] != 'TABLE':
            continue

        table_cells = []
        for rel in block.get('Relationships', []):
            if rel['Type'] == 'CHILD':
                for child_id in rel['Ids']:
                    child = block_map.get(child_id)
                    if child and child['BlockType'] == 'CELL':
                        table_cells.append(child)

        if not table_cells:
            continue

        max_row = max(c['RowIndex'] for c in table_cells)
        max_col = max(c['ColumnIndex'] for c in table_cells)

        grid = [["" for _ in range(max_col)] for _ in range(max_row)]

        for cell in table_cells:
            r = cell['RowIndex'] - 1
            c = cell['ColumnIndex'] - 1

            cell_text_parts = []
            for rel in cell.get('Relationships', []):
                if rel['Type'] == 'CHILD':
                    for child_id in rel['Ids']:
                        child_block = block_map.get(child_id)
                        if child_block and child_block['BlockType'] in ('WORD', 'LINE'):
                            cell_text_parts.append(child_block['Text'])

            grid[r][c] = " ".join(cell_text_parts).strip()

        tables_data.append(grid)

    return tables_data
